UPDATE "MAE_REQUIREMENT" SET "C_DESCRIPTION" = 'Realizar cambios en el sistema de gestión de seguridad de la información, si es necesario. Las acciones correctivas deben ser apropiadas a los efectos de las no conformidades encontradas.' WHERE "N_REQUIREMENT_ID_PK" = 120;
UPDATE "MAE_REQUIREMENT" SET "C_DESCRIPTION" = 'Mantener información documentada como evidencia de la naturaleza de las no conformidades y cualquier acción posterior tomada.' WHERE "N_REQUIREMENT_ID_PK" = 121;
UPDATE "MAE_REQUIREMENT" SET "C_DESCRIPTION" = 'Mantener información documentada como evidencia de los resultados de cualquier acción correctiva.' WHERE "N_REQUIREMENT_ID_PK" = 122;
UPDATE "MAE_REQUIREMENT" SET "C_DESCRIPTION" = 'La organización debe mejorar continuamente la idoneidad, adecuación y eficacia del sistema de gestión de la seguridad de la información.' WHERE "N_REQUIREMENT_ID_PK" = 123;
