-- Verificacion post-ejecucion: cuantas clausulas de ISO 27001 (4-10) siguen sin descripcion.
-- El numero esperado (20) son las filas contenedoras sin texto propio en la norma, detalladas
-- arriba -- no es un error.
SELECT count(*) as sin_descripcion_ok_son_contenedoras
FROM "MAE_REQUIREMENT"
WHERE "N_STANDARD_ID" = 4 AND "N_IS_DELETED" IS DISTINCT FROM true
  AND ("C_DESCRIPTION" IS NULL OR "C_DESCRIPTION" = '');
